var app = new Vue({
  el: "#app",
  delimiters: ["[[", "]]"],
  data: {
    contentText: "",
  },
  methods: {
    getData() {
      const path = window.location.origin + "/dashboard/welcomes/data";
      axios
        .get(path)
        .then((response) => {
          this.contentText = response.data;
        })
        .catch((error) => {
          console.log(error);
        });
    },
    updatePasive() {
      const path = window.location.origin + "/dashboard/welcomes";
      axios
        .post(path, {
          data: this.contentText,
        })
        .catch((error) => {
          console.log(error);
        });
    },
  },
  created() {
    this.getData();
  },
});
